// The Error Trigger gives us the failed run: which workflow, which step, what error.
const e = $input.first().json;
const ex = e.execution || {};
const wf = e.workflow || {};

// Only LeadPilot workflows (IDs starting with "lp") are escalated. Clicking "Execute workflow" on
// THIS workflow makes n8n send fake sample data ("Example Workflow"), which must never reach the
// dashboard as a real problem. Other workflows in this n8n are not ours either.
if (!String(wf.id || '').startsWith('lp')) return [];
const names = { lpWf1HotLeadAlrt: 'Hot-lead alert', lpWf2SendFollow1: 'Send approved follow-up', lpWf3HealthMon01: 'Health monitor', lpWf5RecoverySwp: 'Recovery sweep' };

// Error texts can contain URLs with secrets in them: hide them, keep it short.
const clean = (t) => String(t || 'Unknown error').replace(/https?:\/\/\S+/gi, '[URL hidden]').replace(/\s+/g, ' ').trim().slice(0, 250);

const workflow = names[wf.id] || String(wf.name || 'Unknown workflow').slice(0, 80);
const failedNode = String(ex.lastNodeExecuted || 'unknown step').slice(0, 60);
const error = clean(ex.error && ex.error.message);
// A trigger failure has no execution ID: make one, so the run can still be recorded.
const executionId = String(ex.id || 'trigger-' + Date.now());
const message = 'NEEDS A PERSON: ' + workflow + ' failed at "' + failedNode + '": ' + error + (ex.id ? ' (n8n run #' + ex.id + ')' : '');

return [{ json: { workflow, failedNode, error, executionId, message, leadId: null } }];

// If the backend is down (e.g. a WF3 outage) or refused it, nothing was written. Fail THIS run on
// purpose, so the escalation is at least visible (red) in n8n > Executions. An error
// workflow never triggers itself, so this cannot loop.
const r = $('Escalate on the dashboard').first().json;
const ok = !r.error && r.statusCode >= 200 && r.statusCode < 300;
if (!ok) {
  throw new Error('Could not reach the backend (' + (r.statusCode ? 'HTTP ' + r.statusCode : 'no answer') + ') - this escalation is ONLY visible here in n8n. ' + $('Prepare the escalation').first().json.message.replace(/: /g, ' - '));
}
return $input.all();
